import { useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { showSnackbar, UploadMedia } from "../../redux/slices/app";
import webSocketService from "../../webSocketService";
import { alpha, styled } from "@mui/material/styles";
import { Box, IconButton, Menu, MenuItem, Stack, TextField, Tooltip, Typography } from "@mui/material";
import { File, Image, Paperclip, Smiley } from "phosphor-react";
import MediaDialog from "./MediaDialog";

const StyledInput = styled(TextField)(({ theme }) => ({
  flex: 1,
  "& .MuiOutlinedInput-root": {
    padding: "7px 8px 7px 4px",
    borderRadius: 18,
    backgroundColor: alpha(theme.palette.text.primary, theme.palette.mode === "light" ? 0.045 : 0.07),
    "& fieldset": { border: 0 },
    "&:hover fieldset": { border: 0 },
    "&.Mui-focused": { boxShadow: `0 0 0 3px ${alpha(theme.palette.primary.main, 0.11)}` },
  },
  "& textarea": { lineHeight: 1.55, padding: "8px 4px !important" },
}));

const ChatInput = ({ openPicker, setOpenPicker, setValue, value, inputRef, handleSendMessage, isGroupChat = false, currentConversation }) => {
  const dispatch = useDispatch();
  const userId = window.localStorage.getItem("user_id");
  const { room_id } = useSelector((state) => state.app);
  const [attachmentAnchor, setAttachmentAnchor] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [fileType, setFileType] = useState(null);
  const [progress, setProgress] = useState(0);
  const [uploading, setUploading] = useState(false);
  const mediaInput = useRef(null);
  const fileInput = useRef(null);

  const handleFileSelect = (event) => {
    const file = event.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      setFileType(file.type);
    }
    event.target.value = "";
  };

  const handleSendMedia = () => {
    if (!room_id || !selectedFile) return;
    setUploading(true);
    dispatch(UploadMedia({ file: selectedFile }, setProgress)).then((response) => {
      const fileUrl = response.data.fileUrl;
      const media = fileType.startsWith("image") || fileType.startsWith("video");
      webSocketService.sendMessage(isGroupChat ? "/app/group_media_message" : "/app/media_message", JSON.stringify({
        media: fileUrl,
        message: value,
        ...(isGroupChat ? { group_id: room_id } : { conversation_id: room_id, to: currentConversation?.user_id }),
        from: userId,
        type: media ? "MEDIA" : "DOCUMENT",
        mediaType: fileType.startsWith("image") ? "image" : fileType.startsWith("video") ? "video" : selectedFile.name,
      }));
      setSelectedFile(null);
      setUploading(false);
      setProgress(0);
      setValue("");
    }).catch(() => {
      setUploading(false);
      setProgress(0);
      dispatch(showSnackbar({ severity: "error", message: "File upload failed" }));
    });
  };

  return (
    <>
      <StyledInput
        inputRef={inputRef}
        value={value}
        onChange={(event) => setValue(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "Enter" && !event.shiftKey) {
            event.preventDefault();
            handleSendMessage();
          }
        }}
        fullWidth
        multiline
        maxRows={5}
        placeholder="Message..."
        aria-label="Message"
        InputProps={{
          startAdornment: (
            <Tooltip title="Add attachment">
              <IconButton aria-label="Add attachment" onClick={(event) => setAttachmentAnchor(event.currentTarget)} sx={{ color: "text.secondary" }}>
                <Paperclip size={21} />
              </IconButton>
            </Tooltip>
          ),
          endAdornment: (
            <Tooltip title="Emoji">
              <IconButton aria-label="Choose emoji" onClick={() => setOpenPicker(!openPicker)} sx={{ color: openPicker ? "primary.main" : "text.secondary" }}>
                <Smiley size={21} />
              </IconButton>
            </Tooltip>
          ),
        }}
      />
      <Menu anchorEl={attachmentAnchor} open={Boolean(attachmentAnchor)} onClose={() => setAttachmentAnchor(null)} anchorOrigin={{ vertical: "top", horizontal: "left" }} transformOrigin={{ vertical: "bottom", horizontal: "left" }}>
        <MenuItem onClick={() => { setAttachmentAnchor(null); mediaInput.current?.click(); }}>
          <Stack direction="row" spacing={1.25} alignItems="center"><Image size={19} /><Box><Typography variant="body2">Photos and videos</Typography><Typography variant="caption" color="text.secondary">Share visual moments</Typography></Box></Stack>
        </MenuItem>
        <MenuItem onClick={() => { setAttachmentAnchor(null); fileInput.current?.click(); }}>
          <Stack direction="row" spacing={1.25} alignItems="center"><File size={19} /><Box><Typography variant="body2">Document</Typography><Typography variant="caption" color="text.secondary">PDF, text, and more</Typography></Box></Stack>
        </MenuItem>
      </Menu>
      <input ref={mediaInput} hidden accept="image/*,video/*" type="file" onChange={handleFileSelect} />
      <input ref={fileInput} hidden accept="application/*,text/*" type="file" onChange={handleFileSelect} />
      {Boolean(selectedFile) && (
        <MediaDialog open handleClose={() => setSelectedFile(null)} fileType={fileType} handleSend={handleSendMedia} file={selectedFile} inputRef={inputRef} setSelectedFile={setSelectedFile} value={value} setValue={setValue} uploading={uploading} progress={progress} />
      )}
    </>
  );
};

export default ChatInput;
