import { Box, IconButton, Stack, Tooltip } from "@mui/material";
import { PaperPlaneTilt } from "phosphor-react";
import { alpha, useTheme } from "@mui/material/styles";
import React, { useEffect, useRef, useState } from "react";
import useResponsive from "../../hooks/useResponsive";
import data from "@emoji-mart/data";
import Picker from "@emoji-mart/react";
import { useDispatch, useSelector } from "react-redux";
import webSocketService from "../../webSocketService";
import { showSnackbar } from "../../redux/slices/app";
import ChatInput from "./ChatInput";

const containsUrl = (text) => /(https?:\/\/[^\s]+)/g.test(text);

const Footer = () => {
  const theme = useTheme();
  const { current_conversation } = useSelector((state) => state.conversation.direct_chat);
  const dispatch = useDispatch();
  const userId = window.localStorage.getItem("user_id");
  const isMobile = !useResponsive("up", "md");
  const { room_id, chat_type } = useSelector((state) => state.app);
  const group = chat_type === "group";
  const [openPicker, setOpenPicker] = useState(false);
  const [value, setValue] = useState("");
  const inputRef = useRef(null);
  const pickerRef = useRef(null);

  useEffect(() => {
    const close = (event) => {
      if (pickerRef.current && !pickerRef.current.contains(event.target)) setOpenPicker(false);
    };
    document.addEventListener("mousedown", close);
    return () => document.removeEventListener("mousedown", close);
  }, []);

  const insertEmoji = (emoji) => {
    const input = inputRef.current;
    const start = input?.selectionStart ?? value.length;
    const end = input?.selectionEnd ?? value.length;
    setValue(`${value.substring(0, start)}${emoji}${value.substring(end)}`);
    requestAnimationFrame(() => input?.focus());
  };

  const send = () => {
    const message = value.trim();
    if (!room_id) return dispatch(showSnackbar({ severity: "error", message: "Select a conversation first" }));
    if (!message) return;
    webSocketService.sendMessage(group ? "/app/group_text_message" : "/app/text_message", JSON.stringify({
      message,
      ...(group ? { group_id: room_id } : { conversation_id: room_id, to: current_conversation?.user_id }),
      from: userId,
      type: containsUrl(message) ? "LINK" : "TEXT",
    }));
    setValue("");
    setOpenPicker(false);
  };

  return (
    <Box ref={pickerRef} sx={{ position: "relative", zIndex: 3, px: { xs: 1.25, sm: 2.5 }, py: { xs: 1.25, sm: 2 }, bgcolor: alpha(theme.palette.background.paper, 0.88), borderTop: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, backdropFilter: "blur(24px)" }}>
      {openPicker && (
        <Box sx={{ position: "absolute", zIndex: 20, bottom: "calc(100% + 8px)", right: { xs: 12, sm: 24 }, filter: "drop-shadow(0 20px 40px rgba(0,0,0,.18))" }}>
          <Picker theme={theme.palette.mode} data={data} previewPosition="none" skinTonePosition="none" onEmojiSelect={(emoji) => insertEmoji(emoji.native)} />
        </Box>
      )}
      <Stack direction="row" alignItems="flex-end" spacing={1.25} sx={{ width: "100%" }}>
        <ChatInput inputRef={inputRef} value={value} setValue={setValue} openPicker={openPicker} setOpenPicker={setOpenPicker} handleSendMessage={send} isGroupChat={group} currentConversation={current_conversation} />
        <Tooltip title="Send message">
          <span>
            <IconButton
              aria-label="Send message"
              disabled={!value.trim()}
              onClick={send}
              sx={{ width: isMobile ? 45 : 48, height: isMobile ? 45 : 48, color: "white", background: value.trim() ? "linear-gradient(135deg, #628BFF, #4F70E8)" : alpha(theme.palette.text.secondary, 0.15), boxShadow: value.trim() ? "0 9px 22px rgba(79,124,255,.3)" : "none", "&.Mui-disabled": { color: alpha(theme.palette.text.secondary, 0.5) }, "&:hover": { background: "linear-gradient(135deg, #6B92FF, #4F70E8)" } }}
            >
              <PaperPlaneTilt size={20} weight="fill" />
            </IconButton>
          </span>
        </Tooltip>
      </Stack>
    </Box>
  );
};

export default Footer;
