import React from "react";
import { Avatar, Box, IconButton, Menu, MenuItem, Stack, Tooltip, Typography } from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import { Checks, DotsThree, DownloadSimple, File } from "phosphor-react";
import Embed from "react-embed";
import { useDispatch } from "react-redux";
import { DeleteGroupMessage, DeleteMessage } from "../../redux/slices/conversation";
import { convertToIST } from "../../utils/formatTime";
import truncateString from "../../utils/truncate";
import { extractURL, linkify } from "../../utils/urlProcess";

const MessageOption = ({ id, index, room_id, chat_type }) => {
  const [anchor, setAnchor] = React.useState(null);
  const dispatch = useDispatch();
  const userId = window.localStorage.getItem("user_id");

  const remove = async () => {
    if (chat_type === "group") {
      await dispatch(DeleteGroupMessage({ id, group_id: room_id, user_id: userId }));
    } else {
      await dispatch(DeleteMessage({ id, index, room_id, user_id: userId }));
    }
    setAnchor(null);
  };

  return (
    <>
      <IconButton
        className="message-options"
        aria-label="Message options"
        onClick={(event) => setAnchor(event.currentTarget)}
        size="small"
        sx={{ opacity: { xs: 1, md: 0 }, color: "text.secondary" }}
      >
        <DotsThree size={18} weight="bold" />
      </IconButton>
      <Menu anchorEl={anchor} open={Boolean(anchor)} onClose={() => setAnchor(null)}>
        <MenuItem onClick={remove} sx={{ color: "error.main", minWidth: 150 }}>Delete for me</MenuItem>
      </Menu>
    </>
  );
};

const MessageMeta = ({ el }) => (
  <Stack direction="row" alignItems="center" justifyContent="flex-end" spacing={0.4} sx={{ mt: 0.35, opacity: 0.78 }}>
    <Typography sx={{ fontSize: 10.5, lineHeight: 1.2, color: el.incoming ? "text.secondary" : "rgba(255,255,255,.86)" }}>
      {convertToIST(el.time)}
    </Typography>
    {el.outgoing && <Checks size={13} color="rgba(255,255,255,.9)" />}
  </Stack>
);

const MessageShell = ({ el, index, room_id, menu, chat_type, current_group, children, wide = false }) => {
  const theme = useTheme();
  const groupIncoming = chat_type === "group" && el.incoming;
  const sender = current_group?.members?.find((member) => member.id?.toString() === el.sender_id?.toString());

  return (
    <Stack
      direction="row"
      alignItems="flex-end"
      spacing={0.75}
      className="message-container"
      sx={{
        width: "100%",
        justifyContent: el.incoming ? "flex-start" : "flex-end",
        py: 0.25,
        animation: "messageIn 220ms cubic-bezier(.2,.8,.2,1) both",
        "@keyframes messageIn": { from: { opacity: 0, transform: "translateY(7px) scale(.985)" }, to: { opacity: 1, transform: "none" } },
        "&:hover .message-options": { opacity: 1 },
      }}
    >
      {menu && !el.incoming && <MessageOption id={el.id} index={index} room_id={room_id} chat_type={chat_type} />}
      {groupIncoming && (
        <Tooltip title={el.sender_name || "Group member"} placement="left">
          <Avatar src={sender?.avatar} alt={el.sender_name} sx={{ width: 30, height: 30, mb: 0.5, fontSize: 12, bgcolor: alpha(theme.palette.primary.main, 0.14), color: "primary.main" }}>
            {el.sender_name?.charAt(0)?.toUpperCase()}
          </Avatar>
        </Tooltip>
      )}
      <Box
        sx={{
          position: "relative",
          maxWidth: wide ? { xs: "84vw", sm: 470 } : { xs: "78vw", sm: 560 },
          minWidth: 92,
          px: wide ? 1 : 1.65,
          py: wide ? 1 : 1.15,
          color: el.incoming ? "text.primary" : "common.white",
          bgcolor: el.incoming ? theme.palette.background.paper : theme.palette.primary.main,
          backgroundImage: el.incoming ? "none" : "linear-gradient(145deg, #5C86FF 0%, #496FE8 100%)",
          border: `1px solid ${el.incoming ? alpha(theme.palette.text.primary, 0.08) : alpha("#FFFFFF", 0.1)}`,
          borderRadius: el.incoming ? "20px 20px 20px 6px" : "20px 20px 6px 20px",
          boxShadow: el.incoming
            ? (theme.palette.mode === "light" ? "0 5px 18px rgba(34,45,70,.08)" : "0 5px 18px rgba(0,0,0,.22)")
            : "0 8px 22px rgba(79,124,255,.22)",
          overflow: "hidden",
        }}
      >
        {groupIncoming && el.sender_name && (
          <Typography noWrap sx={{ mb: 0.45, color: "primary.main", fontSize: 11.5, fontWeight: 800 }}>{el.sender_name}</Typography>
        )}
        {children}
        <MessageMeta el={el} />
      </Box>
      {menu && el.incoming && <MessageOption id={el.id} index={index} room_id={room_id} chat_type={chat_type} />}
    </Stack>
  );
};

const TextMsg = (props) => {
  const { el } = props;
  return (
    <MessageShell {...props}>
      <Typography sx={{ fontSize: 14.5, lineHeight: 1.55, whiteSpace: "pre-wrap", overflowWrap: "anywhere", fontWeight: 500 }}>
        {el.message}
      </Typography>
    </MessageShell>
  );
};

const MediaMsg = (props) => {
  const { el } = props;
  return (
    <MessageShell {...props} wide>
      <Stack spacing={0.9}>
        <Box component="a" href={el.media} target="_blank" rel="noopener noreferrer" sx={{ display: "block", overflow: "hidden", borderRadius: "15px", bgcolor: "rgba(0,0,0,.12)" }}>
          {el.mediaType === "image" ? (
            <Box component="img" src={el.media} alt={el.message || "Shared media"} sx={{ display: "block", maxHeight: 390, width: "100%", objectFit: "cover", transition: "transform 240ms ease", "&:hover": { transform: "scale(1.015)" } }} />
          ) : (
            <Box component="video" controls sx={{ display: "block", maxHeight: 390, maxWidth: "100%", borderRadius: "15px" }}><source src={el.media} /></Box>
          )}
        </Box>
        {el.message && <Typography sx={{ px: 0.5, fontSize: 14, lineHeight: 1.5 }}>{el.message}</Typography>}
      </Stack>
    </MessageShell>
  );
};

const DocMsg = (props) => {
  const { el } = props;
  const theme = useTheme();
  return (
    <MessageShell {...props} wide>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ minWidth: { xs: 230, sm: 300 }, p: 1.25, borderRadius: "15px", bgcolor: el.incoming ? alpha(theme.palette.text.primary, 0.04) : alpha("#FFFFFF", 0.12) }}>
        <Box sx={{ width: 44, height: 44, flexShrink: 0, borderRadius: "13px", display: "grid", placeItems: "center", bgcolor: el.incoming ? alpha(theme.palette.primary.main, 0.11) : alpha("#FFFFFF", 0.14), color: el.incoming ? "primary.main" : "white" }}><File size={22} weight="duotone" /></Box>
        <Stack minWidth={0} flex={1}>
          <Typography variant="subtitle2" noWrap>{truncateString(el.mediaType || "Document", 30)}</Typography>
          <Typography variant="caption" sx={{ opacity: 0.72 }}>Shared document</Typography>
        </Stack>
        <Tooltip title="Download">
          <IconButton aria-label="Download file" onClick={() => window.open(el.media, "_blank")} sx={{ color: "inherit" }}><DownloadSimple size={20} /></IconButton>
        </Tooltip>
      </Stack>
      {el.message && <Typography sx={{ mt: 1, px: 0.5, fontSize: 14 }}>{el.message}</Typography>}
    </MessageShell>
  );
};

const LinkMsg = (props) => {
  const { el } = props;
  const theme = useTheme();
  const url = extractURL(el.message);
  return (
    <MessageShell {...props} wide>
      <Stack spacing={1}>
        {url && (
          <Box sx={{ maxHeight: 280, overflow: "hidden", borderRadius: "14px", bgcolor: "background.paper", color: "text.primary", "& > div": { maxWidth: "100%" } }}>
            <Embed isDark={theme.palette.mode === "dark"} url={url} />
          </Box>
        )}
        <Typography component="div" sx={{ fontSize: 14, overflowWrap: "anywhere", "& a": { color: el.incoming ? "primary.main" : "white", fontWeight: 700 } }}>
          {linkify(el.message, theme)}
        </Typography>
      </Stack>
    </MessageShell>
  );
};

const ReplyMsg = (props) => {
  const { el } = props;
  return (
    <MessageShell {...props}>
      <Stack spacing={1}>
        <Box sx={{ px: 1.25, py: 1, borderRadius: "12px", borderLeft: "3px solid", borderColor: el.incoming ? "primary.main" : "rgba(255,255,255,.8)", bgcolor: el.incoming ? "action.hover" : "rgba(255,255,255,.12)" }}>
          <Typography sx={{ fontSize: 12.5, opacity: 0.8 }}>{el.message}</Typography>
        </Box>
        <Typography sx={{ fontSize: 14.5, lineHeight: 1.5 }}>{el.reply}</Typography>
      </Stack>
    </MessageShell>
  );
};

const Timeline = ({ el }) => {
  const theme = useTheme();
  return (
    <Stack direction="row" alignItems="center" justifyContent="center" sx={{ py: 2 }}>
      <Typography sx={{ color: "text.secondary", fontSize: 10.5, fontWeight: 800, bgcolor: alpha(theme.palette.background.paper, 0.82), border: `1px solid ${alpha(theme.palette.text.primary, 0.07)}`, px: 1.4, py: 0.55, borderRadius: 10, backdropFilter: "blur(12px)", textTransform: "uppercase", letterSpacing: ".09em" }}>
        {el.text}
      </Typography>
    </Stack>
  );
};

export { Timeline, MediaMsg, LinkMsg, DocMsg, TextMsg, ReplyMsg };
