import React from "react";
import { Avatar, Box, Divider, IconButton, Menu, MenuItem, Stack, Tooltip, Typography } from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import { ArrowLeft, DotsThree, Info, MagnifyingGlass, Phone, VideoCamera } from "phosphor-react";
import useResponsive from "../../hooks/useResponsive";
import { SelectConversation, ToggleSidebar, UpdateSidebarType } from "../../redux/slices/app";
import { useDispatch, useSelector } from "react-redux";
import { StartAudioCall } from "../../redux/slices/audioCall";
import { StartVideoCall } from "../../redux/slices/videoCall";
import { DeleteChat, LeaveGroupConversation } from "../../redux/slices/conversation";

const ChatHeader = () => {
  const userId = window.localStorage.getItem("user_id");
  const dispatch = useDispatch();
  const isMobile = !useResponsive("up", "md");
  const theme = useTheme();
  const { chat_type, sideBar } = useSelector((state) => state.app);
  const { current_conversation } = useSelector((state) => state.conversation.direct_chat);
  const { current_group } = useSelector((state) => state.conversation.group_chat);
  const group = chat_type === "group";
  const active = group ? current_group : current_conversation;
  const [anchor, setAnchor] = React.useState(null);

  const openDetails = () => {
    const type = group ? "GROUP" : "CONTACT";
    dispatch(UpdateSidebarType(type));
    if (!sideBar.open) dispatch(ToggleSidebar());
  };

  const actions = group ? [
    { label: "Group information", action: openDetails },
    {
      label: "Leave group",
      danger: true,
      hidden: active?.owner_id === userId,
      action: async () => {
        if (!active?.id) return;
        const ok = await dispatch(LeaveGroupConversation({ group_id: active.id }));
        if (ok) dispatch(SelectConversation({ room_id: null, chat_type: null }));
      },
    },
  ] : [
    { label: "Contact information", action: openDetails },
    { label: "Mute notifications", action: () => {} },
    { label: "Clear conversation", danger: true, action: () => dispatch(DeleteChat({ room_id: active?.id, user_id: userId })) },
  ];

  return (
    <Box
      component="header"
      sx={{
        position: "relative",
        zIndex: 4,
        minHeight: 78,
        px: { xs: 1.5, sm: 2.5 },
        display: "flex",
        alignItems: "center",
        bgcolor: alpha(theme.palette.background.paper, 0.84),
        borderBottom: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`,
        backdropFilter: "blur(24px) saturate(150%)",
      }}
    >
      <Stack direction="row" alignItems="center" justifyContent="space-between" width="100%" minWidth={0}>
        <Stack direction="row" alignItems="center" spacing={1.25} minWidth={0}>
          {isMobile && (
            <IconButton aria-label="Back to conversations" onClick={() => dispatch(SelectConversation({ room_id: null, chat_type: null }))}>
              <ArrowLeft size={21} />
            </IconButton>
          )}
          <Stack direction="row" alignItems="center" spacing={1.4} minWidth={0} onClick={openDetails} sx={{ cursor: "pointer" }}>
            <Box sx={{ position: "relative" }}>
              <Avatar alt={active?.name} src={active?.img} sx={{ width: 47, height: 47, bgcolor: alpha(theme.palette.primary.main, 0.12), color: "primary.main", fontWeight: 800 }}>
                {active?.name?.charAt(0)?.toUpperCase()}
              </Avatar>
              {!group && active?.online && <Box sx={{ position: "absolute", right: 0, bottom: 1, width: 13, height: 13, borderRadius: "50%", bgcolor: "success.main", border: `3px solid ${theme.palette.background.paper}` }} />}
            </Box>
            <Stack spacing={0.15} minWidth={0}>
              <Typography variant="subtitle1" noWrap sx={{ fontWeight: 800 }}>{active?.name || "Conversation"}</Typography>
              <Typography variant="caption" noWrap sx={{ color: group || active?.online ? "success.main" : "text.secondary", fontWeight: 600 }}>
                {group ? `${active?.members?.length || 0} members` : active?.online ? "Active now" : "Offline"}
              </Typography>
            </Stack>
          </Stack>
        </Stack>

        <Stack direction="row" alignItems="center" spacing={{ xs: 0.25, sm: 0.75 }}>
          {!group && (
            <Tooltip title="Voice call"><IconButton aria-label="Voice call" onClick={() => dispatch(StartAudioCall(active?.user_id))}><Phone size={20} /></IconButton></Tooltip>
          )}
          {!group && (
            <Tooltip title="Video call"><IconButton aria-label="Video call" onClick={() => dispatch(StartVideoCall(active?.user_id))}><VideoCamera size={20} /></IconButton></Tooltip>
          )}
          {!isMobile && <Tooltip title="Search messages"><IconButton aria-label="Search messages"><MagnifyingGlass size={20} /></IconButton></Tooltip>}
          {!isMobile && <Tooltip title={group ? "Group information" : "Contact information"}><IconButton aria-label="Conversation information" onClick={openDetails}><Info size={20} /></IconButton></Tooltip>}
          <Divider orientation="vertical" flexItem sx={{ mx: 0.5, my: 0.75 }} />
          <IconButton aria-label="More conversation actions" aria-haspopup="menu" onClick={(event) => setAnchor(event.currentTarget)}>
            <DotsThree size={22} weight="bold" />
          </IconButton>
          <Menu anchorEl={anchor} open={Boolean(anchor)} onClose={() => setAnchor(null)} anchorOrigin={{ vertical: "bottom", horizontal: "right" }} transformOrigin={{ vertical: "top", horizontal: "right" }}>
            {actions.filter((item) => !item.hidden).map((item) => (
              <MenuItem key={item.label} onClick={() => { setAnchor(null); item.action(); }} sx={{ minWidth: 190, color: item.danger ? "error.main" : "text.primary" }}>
                {item.label}
              </MenuItem>
            ))}
          </Menu>
        </Stack>
      </Stack>
    </Box>
  );
};

export default ChatHeader;
