import { Stack, Box, Button, Typography } from "@mui/material";
import React, { useEffect, useMemo, useRef } from "react";
import { useTheme } from "@mui/material/styles";

import { ChatHeader, ChatFooter } from "../../components/Chat";
import useResponsive from "../../hooks/useResponsive";
import { DocMsg, LinkMsg, MediaMsg, ReplyMsg, TextMsg, Timeline, } from "../../sections/main/Conversation";
import { useDispatch, useSelector } from "react-redux";
import {
  FetchGroupMessages,
  SetCurrentGroupMessages,
  SetCurrentMessages,
} from "../../redux/slices/conversation";

const Conversation = ({ isMobile, menu }) => {
  const dispatch = useDispatch();
  const { room_id, chat_type } = useSelector((state) => state.app);
  const { current_messages } = useSelector((state) => state.conversation.direct_chat);
  const { current_group_messages, current_group } = useSelector((state) => state.conversation.group_chat);
  const { messages_cursor, has_more_messages, loading_messages } = useSelector(
    (state) => state.conversation.group_chat
  );

  const activeMessages = useMemo(() => {
    return chat_type === "group" ? current_group_messages : current_messages;
  }, [chat_type, current_group_messages, current_messages]);

  useEffect(() => {
    if (!room_id) return;

    if (chat_type === "group") {
      dispatch(SetCurrentGroupMessages({ room_id }));
      dispatch(FetchGroupMessages({ group_id: room_id }));
    } else {
      dispatch(SetCurrentMessages({ room_id }));
    }
  }, [dispatch, room_id, chat_type]);

  const actualMessages = activeMessages?.filter((entry) => entry.type === "msg") || [];

  return (
    <Box px={isMobile ? 1.5 : 3} py={isMobile ? 2 : 3.5} overflow="hidden">
      <Stack spacing={1.25} sx={{ width: "100%" }}>
        {chat_type === "group" && has_more_messages && (
          <Button
            size="small"
            onClick={() => dispatch(FetchGroupMessages({
              group_id: room_id,
              lastVisible: messages_cursor,
            }))}
            disabled={loading_messages}
            sx={{ alignSelf: "center" }}
          >
            {loading_messages ? "Loading..." : "Load older messages"}
          </Button>
        )}
        {actualMessages.length === 0 && (
          <Stack alignItems="center" spacing={0.75} sx={{ py: 8, opacity: 0.8 }}>
            <Typography variant="subtitle2">A fresh conversation</Typography>
            <Typography variant="caption" color="text.secondary">Send a message to get things started.</Typography>
          </Stack>
        )}
        {actualMessages.length > 0 && activeMessages?.map((el, index) => {
          switch (el?.type) {
            case "divider":
              return (
                // Timeline
                <Timeline key={`divider-${index}-${el?.text}`} el={el} />
              );

            case "msg":
              switch (el?.subtype) {
                case "MEDIA":
                  return (
                    // Media Message
                    <MediaMsg
                      key={el.id || `media-${index}`}
                      el={el}
                      index={index}
                      room_id={room_id}
                      menu={menu}
                      chat_type={chat_type}
                      current_group={current_group}
                    />
                  );

                case "DOCUMENT":
                  return (
                    // Doc Message
                    <DocMsg
                      key={el.id || `doc-${index}`}
                      el={el}
                      index={index}
                      room_id={room_id}
                      menu={menu}
                      chat_type={chat_type}
                      current_group={current_group}
                    />
                  );
                case "LINK":
                  return (
                    //  Link Message
                    <LinkMsg
                      key={el.id || `link-${index}`}
                      el={el}
                      index={index}
                      room_id={room_id}
                      menu={menu}
                      chat_type={chat_type}
                      current_group={current_group}
                    />
                  );

                case "REPLY":
                  return (
                    //  ReplyMessage
                    <ReplyMsg
                      key={el.id || `reply-${index}`}
                      el={el}
                      index={index}
                      room_id={room_id}
                      menu={menu}
                      chat_type={chat_type}
                      current_group={current_group}
                    />
                  );

                default:
                  return (
                    // Text Message
                    <TextMsg
                      key={el.id || `text-${index}`}
                      el={el}
                      index={index}
                      room_id={room_id}
                      menu={menu}
                      chat_type={chat_type}
                      current_group={current_group}
                    />
                  );
              }

            default:
              return null;
          }
        })}
      </Stack>
    </Box>
  );
};

const ChatComponent = () => {
  const isMobile = useResponsive("between", "md", "xs", "sm");
  const theme = useTheme();
  const messageListRef = useRef(null);
  const { chat_type } = useSelector((state) => state.app);

  const { current_messages } = useSelector((state) => state.conversation.direct_chat);
  const { current_group_messages } = useSelector((state) => state.conversation.group_chat);

  const activeMessages = useMemo(() => {
    return chat_type === "group" ? current_group_messages : current_messages;
  }, [chat_type, current_group_messages, current_messages]);
  const lastMessageId = [...(activeMessages || [])].reverse().find((entry) => entry.type === "msg")?.id;

  useEffect(() => {
    if (!messageListRef.current) return;
    messageListRef.current.scrollTo({
      top: messageListRef.current.scrollHeight,
    });
  }, [lastMessageId]);

  return (
    <Stack
      height={"100%"}
      maxHeight={"100vh"}
      width={isMobile ? "100vw" : "auto"}
    >
      {/*  */}
      <ChatHeader />
      <Box
        ref={messageListRef}
        width={"100%"}
        sx={{
          position: "relative",
          flexGrow: 1,
          overflowY: "scroll",
          scrollBehavior: "smooth",
          backgroundColor: theme.palette.background.default,
          backgroundImage: theme.palette.mode === "light"
            ? "radial-gradient(circle at 20% 15%, rgba(79,124,255,.07), transparent 24%), radial-gradient(circle at 82% 76%, rgba(139,92,246,.05), transparent 22%)"
            : "radial-gradient(circle at 20% 15%, rgba(79,124,255,.09), transparent 24%), radial-gradient(circle at 82% 76%, rgba(139,92,246,.06), transparent 22%)",
        }}
      >
        <Conversation menu={true} isMobile={isMobile} />
      </Box>

      {/*  */}
      <ChatFooter />
    </Stack>
  );
};

export default ChatComponent;

export { Conversation };
